#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct MinHeap {
    int *data;
    int size;
    int capacity;
} MinHeap;

MinHeap* create_heap(int capacity) {
    MinHeap *h = (MinHeap *)malloc(sizeof(MinHeap));
    h->data = (int *)malloc(sizeof(int) * capacity);
    h->size = 0;
    h->capacity = capacity;
    return h;
}

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void sift_up(MinHeap *h, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (h->data[idx] < h->data[parent]) {
            swap(&h->data[idx], &h->data[parent]);
            idx = parent;
        } else {
            break;
        }
    }
}

void sift_down(MinHeap *h, int idx) {
    while (2 * idx + 1 < h->size) {
        int smallest = idx;
        int left = 2 * idx + 1;
        int right = 2 * idx + 2;

        if (left < h->size && h->data[left] < h->data[smallest]) smallest = left;
        if (right < h->size && h->data[right] < h->data[smallest]) smallest = right;

        if (smallest != idx) {
            swap(&h->data[idx], &h->data[smallest]);
            idx = smallest;
        } else {
            break;
        }
    }
}

void insert(MinHeap *h, int val) {
    if (h->size >= h->capacity) {
        h->capacity *= 2;
        h->data = (int *)realloc(h->data, sizeof(int) * h->capacity);
    }
    h->data[h->size] = val;
    sift_up(h, h->size);
    h->size++;
}

void extract_min(MinHeap *h) {
    if (h->size == 0) {
        printf("EMPTY\n");
        return;
    }
    int min_val = h->data[0];
    h->data[0] = h->data[h->size - 1];
    h->size--;
    sift_down(h, 0);
    printf("%d\n", min_val);
}

void get_min(MinHeap *h) {
    if (h->size == 0) {
        printf("EMPTY\n");
    } else {
        printf("%d\n", h->data[0]);
    }
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    MinHeap *h = create_heap(1024);

    char cmd[32];
    while (q--) {
        scanf("%s", cmd);
        if (strcmp(cmd, "insert") == 0) {
            int x;
            scanf("%d", &x);
            insert(h, x);
        } else if (strcmp(cmd, "extractMin") == 0) {
            extract_min(h);
        } else if (strcmp(cmd, "getMin") == 0) {
            get_min(h);
        } else if (strcmp(cmd, "size") == 0) {
            printf("%d\n", h->size);
        }
    }

    free(h->data);
    free(h);
