void insert_hash(int val) {
    unsigned int idx = hash_fn(val);
    HashNode *curr = table[idx];
    while (curr) {
        if (curr->val == val) {
            curr->count++;
            return;
        }
        curr = curr->next;
    }
    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    node->val = val;
    node->count = 1;
    node->next = table[idx];
    table[idx] = node;
}

int compare_pairs(const void *a, const void *b) {
    Pair *p1 = (Pair *)a;
    Pair *p2 = (Pair *)b;
    if (p1->count != p2->count) {
        return p2->count - p1->count; // Descending by frequency
    }
    return p1->val - p2->val; // Ascending by val
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    for (int i = 0; i < HASH_SIZE; i++) table[i] = NULL;

