#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { EMPTY, OCCUPIED, TOMBSTONE } State;

typedef struct {
    int key;
    int val;
    State state;
} Slot;

typedef struct {
    Slot *slots;
    int capacity;
    int occupied_count;
    int tombstone_count;
} HashTable;

unsigned int hash_code(int key, int cap) {
    long long k = key;
    if (k < 0) k = -k;
    return (unsigned int)(k % cap);
}

HashTable* create_table(int cap) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->capacity = cap;
    ht->occupied_count = 0;
    ht->tombstone_count = 0;
    ht->slots = (Slot *)calloc(cap, sizeof(Slot));
    return ht;
}

void rehash(HashTable *ht) {
    int old_cap = ht->capacity;
    Slot *old_slots = ht->slots;

    ht->capacity = old_cap * 2;
    ht->slots = (Slot *)calloc(ht->capacity, sizeof(Slot));
    ht->occupied_count = 0;
    ht->tombstone_count = 0;

    for (int i = 0; i < old_cap; i++) {
        if (old_slots[i].state == OCCUPIED) {
            int k = old_slots[i].key;
            int v = old_slots[i].val;
            unsigned int base = hash_code(k, ht->capacity);
            for (int step = 0; step < ht->capacity; step++) {
                int idx = (base + step) % ht->capacity;
                if (ht->slots[idx].state == EMPTY) {
                    ht->slots[idx].key = k;
                    ht->slots[idx].val = v;
                    ht->slots[idx].state = OCCUPIED;
                    ht->occupied_count++;
                    break;
                }
            }
        }
    }
    free(old_slots);
}

void insert(HashTable *ht, int key, int val) {
    // Check if key already exists
    unsigned int base = hash_code(key, ht->capacity);
    for (int step = 0; step < ht->capacity; step++) {
        int idx = (base + step) % ht->capacity;
        if (ht->slots[idx].state == OCCUPIED && ht->slots[idx].key == key) {
            ht->slots[idx].val = val;
            return;
        }
        if (ht->slots[idx].state == EMPTY) break;
    }

    // Check load factor threshold: (occupied + tombstones + 1) / capacity >= 0.7
    if ((double)(ht->occupied_count + ht->tombstone_count + 1) / ht->capacity >= 0.7) {
        rehash(ht);
        base = hash_code(key, ht->capacity);
    }

    int first_tombstone = -1;
    for (int step = 0; step < ht->capacity; step++) {
        int idx = (base + step) % ht->capacity;
        if (ht->slots[idx].state == TOMBSTONE && first_tombstone == -1) {
            first_tombstone = idx;
        }
        if (ht->slots[idx].state == EMPTY) {
            int target_idx = (first_tombstone != -1) ? first_tombstone : idx;
            if (target_idx == first_tombstone) ht->tombstone_count--;
            ht->slots[target_idx].key = key;
            ht->slots[target_idx].val = val;
            ht->slots[target_idx].state = OCCUPIED;
            ht->occupied_count++;
            return;
        }
    }
    if (first_tombstone != -1) {
        ht->slots[first_tombstone].key = key;
        ht->slots[first_tombstone].val = val;
        ht->slots[first_tombstone].state = OCCUPIED;
        ht->tombstone_count--;
        ht->occupied_count++;
    }
}

void get(HashTable *ht, int key) {
    unsigned int base = hash_code(key, ht->capacity);
    for (int step = 0; step < ht->capacity; step++) {
        int idx = (base + step) % ht->capacity;
        if (ht->slots[idx].state == OCCUPIED && ht->slots[idx].key == key) {
            printf("%d\n", ht->slots[idx].val);
            return;
        }
        if (ht->slots[idx].state == EMPTY) {
            printf("NOT_FOUND\n");
            return;
        }
    }
    printf("NOT_FOUND\n");
}

void delete_key(HashTable *ht, int key) {
    unsigned int base = hash_code(key, ht->capacity);
    for (int step = 0; step < ht->capacity; step++) {
        int idx = (base + step) % ht->capacity;
        if (ht->slots[idx].state == OCCUPIED && ht->slots[idx].key == key) {
            ht->slots[idx].state = TOMBSTONE;
            ht->occupied_count--;
            ht->tombstone_count++;
            printf("DELETED\n");
            return;
        }
        if (ht->slots[idx].state == EMPTY) {
            printf("NOT_FOUND\n");
            return;
        }
    }
    printf("NOT_FOUND\n");
}

int main(void) {
    int cap, q;
    if (scanf("%d %d", &cap, &q) != 2) return 0;
    HashTable *ht = create_table(cap);

    char cmd[16];
    while (q--) {
        scanf("%s", cmd);
        if (strcmp(cmd, "insert") == 0) {
            int k, v;
            scanf("%d %d", &k, &v);
            insert(ht, k, v);
        } else if (strcmp(cmd, "get") == 0) {
            int k;
            scanf("%d", &k);
            get(ht, k);
        } else if (strcmp(cmd, "delete") == 0) {
            int k;
            scanf("%d", &k);
            delete_key(ht, k);
        }
    }

    free(ht->slots);
    free(ht);
    return 0;
}

