int match_count = 0;
char buffer[128];

void dfs(TrieNode *node, int depth) {
    if (!node) return;
    if (node->is_end_of_word) {
        buffer[depth] = '\0';
        printf("%s\n", buffer);
        match_count++;
    }
    for (int i = 0; i < 26; i++) {
        if (node->children[i]) {
            buffer[depth] = 'a' + i;
            dfs(node->children[i], depth + 1);
